package antigravity

import (
	"context"
	"encoding/json"
	"io"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Antigravity hook name constants — these become subcommands under `entire hooks antigravity`.
//
// Only the hooks with lifecycle significance are installed. agy also offers
// PostToolUse and PostInvocation, but neither maps to an Entire lifecycle
// event (PostInvocation fires before the transcript is written; PostToolUse
// duplicates what PreToolUse already captures) — installing them would spawn
// a no-op `entire` subprocess on every completed tool call and model
// invocation.
const (
	HookNamePreToolUse    = "pre-tool-use"
	HookNamePreInvocation = "pre-invocation"
	HookNameStop          = "stop"
)

// HookNames returns the hook verbs Antigravity supports.
// These become subcommands: entire hooks antigravity <verb>
func (a *AntigravityAgent) HookNames() []string {
	return []string{
		HookNamePreToolUse,
		HookNamePreInvocation,
		HookNameStop,
	}
}

// ParseHookEvent translates an Antigravity hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance.
func (a *AntigravityAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNamePreInvocation:
		return parsePreInvocation(stdin)
	case HookNameStop:
		return parseStop(stdin)
	case HookNamePreToolUse:
		return parsePreToolUse(stdin)
	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// parsePreInvocation handles the PreInvocation hook.
//
// Emits TurnStart ONLY on the first model invocation of a conversation
// (invocationNum == 0). Subsequent PreInvocations within the same
// conversation return nil.
//
// Background: agy's PreInvocation fires per *model invocation*, but Entire's
// TurnStart event is designed for per-*user-prompt*. The framework's TurnStart
// handler re-captures pre-prompt state (preUntrackedFiles, attribution
// baseline) on every call. If we emit TurnStart on every PreInvocation, the
// baseline gets clobbered each time — by the time TurnEnd fires at Stop, the
// pre-state reflects the post-tool-use snapshot, and DetectFileChanges sees
// no new files compared to itself ("no files modified during session,
// skipping checkpoint"). Confirmed by agy traces showing two PreInvocations
// per single-prompt conversation.
//
// agy wire format: invocationNum is **0-indexed** (the docs now state this
// explicitly: "the first invocation is 0"). Real captured stdin from
// agy 1.0.0:
//
//	PreInvocation #1: {"invocationNum":0,"initialNumSteps":1,...}  ← turn start
//	PreInvocation #2: {"invocationNum":1,"initialNumSteps":5,...}  ← follow-up
//
// (initialNumSteps is not a usable "first?" signal — agy inserts the user
// prompt as a step before the first model call, so it's already 1.)
//
// Resumes (agy --continue / --conversation) start with invocationNum > 0, so
// invocationNum alone can't distinguish them from a mid-turn follow-up. We emit
// a TurnStart with SuppressIfSessionActive for every invocationNum > 0; the cli
// dispatcher fires it only when no active session state exists — so a resumed
// turn (state condensed/idle/absent) is tracked, while a genuine follow-up
// (state active mid-turn) is dropped without clobbering the baseline.
//
// Antigravity has no SessionStart hook surface, so there is no path to display
// a "tracked by entire" banner in the agy UI for v1. AntigravityAgent
// intentionally does not implement HookResponseWriter, matching the
// Cursor/OpenCode/Copilot/Pi pattern of silent session tracking.
func parsePreInvocation(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[InvocationPayload](stdin)
	if err != nil {
		return nil, err
	}
	// invocationNum>0 is ambiguous: a mid-turn follow-up model call (must NOT
	// re-fire TurnStart, or the pre-prompt baseline is clobbered) OR the first
	// call of a resumed conversation (agy --continue / --conversation), which
	// starts at invocationNum>0 and MUST be tracked. We can't read session state
	// here (agent packages must not import strategy), so emit a conditional
	// TurnStart and let the dispatcher fire it only when no active session
	// exists.
	return &agent.Event{
		Type:                    agent.TurnStart,
		SessionID:               raw.ConversationID,
		SessionRef:              raw.TranscriptPath,
		Timestamp:               time.Now(),
		SuppressIfSessionActive: raw.InvocationNum != 0,
	}, nil
}

// parseStop handles the Stop hook.
//
// Returns TurnEnd when fullyIdle=true; returns nil when background tasks are
// still running (fullyIdle=false) so the session isn't finalized prematurely.
//
// We map fullyIdle=true to TurnEnd (not SessionEnd) because the framework's
// TurnEnd handler invokes SaveStep — which increments StepCount, writes a
// checkpoint to the shadow branch, and persists FilesTouched into the per-
// session metadata. Without that, the eventual `git commit` finds no shadow
// branch for the session and the cleanup pass at listAllSessionStates removes
// the state file before any checkpoint is condensed. Mapping to SessionEnd
// would mark the session ENDED but never run SaveStep, leaving files_touched
// in a state that never produces a checkpoint commit.
//
// Antigravity's lifecycle gives us exactly one definite "model loop finished"
// moment (Stop with fullyIdle=true), so it's the right anchor for TurnEnd.
// Multi-turn agy sessions get a single TurnEnd at exit, capturing the entire
// turn's work in one checkpoint — a deliberate trade-off vs the per-prompt
// granularity other agents (Gemini, Claude) achieve via separate BeforeAgent
// /AfterAgent or UserPromptSubmit/Stop hooks. See PrepareTranscript below for
// the asynchronous-transcript handling.
func parseStop(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[StopPayload](stdin)
	if err != nil {
		return nil, err
	}
	if !raw.FullyIdle {
		return nil, nil //nolint:nilnil // Background tasks running — do not end session yet
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

// parsePreToolUse handles the PreToolUse hook → ToolUse for mutating tools.
// Returns nil for non-mutating tools (no lifecycle action needed).
func parsePreToolUse(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[PreToolUsePayload](stdin)
	if err != nil {
		return nil, err
	}
	modifiedFiles, newFiles := extractFilesFromToolCall(&raw.ToolCall)
	if modifiedFiles == nil && newFiles == nil {
		return nil, nil //nolint:nilnil // Non-mutating tool — no lifecycle action
	}
	return &agent.Event{
		Type:          agent.ToolUse,
		SessionID:     raw.ConversationID,
		SessionRef:    raw.TranscriptPath,
		ModifiedFiles: modifiedFiles,
		NewFiles:      newFiles,
		Timestamp:     time.Now(),
	}, nil
}

// resolveAgySymlinks resolves symlinks for an absolute path agy sends so it
// matches the symlink-resolved worktree root the framework uses (e.g. macOS
// /tmp → /private/tmp). Without this, FilterAndNormalizePaths produces a
// "../" relative path and drops the file as "outside repo" — silently
// breaking files_touched capture.
//
// We can't EvalSymlinks the path itself because it may not exist yet
// (write_to_file is creating it). We also can't rely on EvalSymlinks of the
// immediate parent because agy can create files in *new* nested directories
// — EvalSymlinks returns an error for any missing component. So we walk up
// until we find an existing ancestor, resolve symlinks there, and reattach
// the missing tail. Returns the input unchanged if the path isn't absolute
// or no ancestor resolves.
func resolveAgySymlinks(p string) string {
	if !filepath.IsAbs(p) {
		return p
	}
	suffix := filepath.Base(p)
	dir := filepath.Dir(p)
	for {
		if resolved, err := filepath.EvalSymlinks(dir); err == nil {
			return filepath.Join(resolved, suffix)
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return p // reached root without finding a resolvable ancestor
		}
		suffix = filepath.Join(filepath.Base(dir), suffix)
		dir = parent
	}
}

// extractFilesFromToolCall inspects the tool call and returns the files it
// will modify or create. Both slices are nil for non-mutating tools.
//
// agy 1.0.0 wire-format quirk: every tool arg value is double-encoded as a
// JSON string containing the actual value. So instead of:
//
//	{"TargetFile": "/path/to/file", "Overwrite": true}
//
// the hook actually receives:
//
//	{"TargetFile": "\"/path/to/file\"", "Overwrite": "true"}
//
// This is undocumented but consistent. To stay robust against both the
// docs-shape format and the actual agy 1.0.0 format, we parse args into raw
// values and unquote/coerce on the way out.
func extractFilesFromToolCall(tc *ToolCall) (modifiedFiles, newFiles []string) {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(tc.Args, &raw); err != nil {
		return nil, nil
	}

	switch tc.Name {
	case "write_to_file":
		targetFile := resolveAgySymlinks(decodeAgyString(raw["TargetFile"]))
		if targetFile == "" {
			return nil, nil
		}
		if decodeAgyBool(raw["Overwrite"]) {
			return []string{targetFile}, nil
		}
		return nil, []string{targetFile}

	case "replace_file_content", "multi_replace_file_content":
		targetFile := resolveAgySymlinks(decodeAgyString(raw["TargetFile"]))
		if targetFile == "" {
			return nil, nil
		}
		return []string{targetFile}, nil

	default:
		return nil, nil
	}
}

// decodeAgyString handles agy's double-encoded string args. Tries the
// docs-shape format first (a plain JSON string), then falls back to the
// agy-actual format (a JSON string whose content is itself a JSON-encoded
// string). Returns "" when neither form decodes cleanly.
func decodeAgyString(raw json.RawMessage) string {
	if len(raw) == 0 {
		return ""
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return ""
	}
	// agy double-encodes — unwrap once more if the inner content is itself JSON-quoted.
	var inner string
	if err := json.Unmarshal([]byte(s), &inner); err == nil {
		return inner
	}
	return s
}

// decodeAgyBool handles agy's double-encoded bool args. Tries the docs-shape
// format (real JSON boolean) first, then the agy-actual format (string "true"
// or "false"). Returns false for any unrecognized shape.
func decodeAgyBool(raw json.RawMessage) bool {
	if len(raw) == 0 {
		return false
	}
	var b bool
	if err := json.Unmarshal(raw, &b); err == nil {
		return b
	}
	var s string
	if err := json.Unmarshal(raw, &s); err == nil {
		return s == "true"
	}
	return false
}

package antigravity

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Ensure AntigravityAgent implements HookSupport
var _ agent.HookSupport = (*AntigravityAgent)(nil)

// AgentsHooksFileName is the hooks file used by Antigravity.
const AgentsHooksFileName = "hooks.json"

// entireHookPrefixes are command prefixes that identify Entire hooks. The
// localDev prefix is the full canonical form (matching cursor/claudecode) —
// a bare "go run " prefix would misclassify any user-authored go-run command
// under the "entire" hooks key as Entire-managed.
var entireHookPrefixes = []string{
	"entire hooks antigravity ",
	`go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `,
}

// InstallHooks installs Antigravity hooks in .agents/hooks.json.
// If localDev is true, hooks point to the local development build.
// If force is true, removes existing Entire hooks before installing.
// Returns the number of hooks installed.
func (a *AntigravityAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
		if err != nil {
			return 0, fmt.Errorf("failed to get current directory: %w", err)
		}
	}

	hooksPath := filepath.Join(repoRoot, ".agents", AgentsHooksFileName)

	// Read and parse existing hooks file, preserving unknown keys
	rawFile := make(map[string]json.RawMessage)
	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
	if readErr == nil {
		if err := json.Unmarshal(existingData, &rawFile); err != nil {
			return 0, fmt.Errorf("failed to parse existing hooks.json: %w", err)
		}
	}

	// Build the candidate Entire hook config
	var cmdPrefix string
	if localDev {
		cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks antigravity `
	} else {
		cmdPrefix = "entire hooks antigravity "
	}

	candidate := buildEntireHookConfig(cmdPrefix, localDev)

	// Title tee: agy's only token-usage surface (same payload as the
	// statusline script). Run this BEFORE the idempotency early-return: the
	// title slot lives in agy's GLOBAL settings.json, independent of this
	// repo's .agents/hooks.json. If repo hooks already match but the global
	// slot is missing or stale (upgrade from a pre-title-tee version, a failed
	// first install, or `entire agent add` without --force), re-running setup
	// must still repair it — otherwise the doctor's "re-run setup" hint is a
	// no-op. InstallTitleTee is itself idempotent. Best-effort: a failure to
	// claim the global slot must not fail repo-level hook setup.
	if err := InstallTitleTee(localDev); err != nil {
		logging.Warn(ctx, "failed to install antigravity title tee",
			"error", err.Error())
	}

	// Idempotency check: compare candidate against existing "entire" entry by
	// re-marshaling both to compact JSON for a stable comparison.
	if !force {
		if existing, ok := rawFile["entire"]; ok {
			var existingCfg HookConfig
			if err := json.Unmarshal(existing, &existingCfg); err == nil {
				existingBytes, err1 := jsonutil.MarshalWithNoHTMLEscape(existingCfg)
				candidateBytes, err2 := jsonutil.MarshalWithNoHTMLEscape(candidate)
				if err1 == nil && err2 == nil && bytes.Equal(existingBytes, candidateBytes) {
					return 0, nil
				}
			}
		}
	}

	// Marshal and insert the "entire" entry (replacing any prior value)
	candidateBytes, err := jsonutil.MarshalWithNoHTMLEscape(candidate)
	if err != nil {
		return 0, fmt.Errorf("failed to marshal hook config: %w", err)
	}
	rawFile["entire"] = candidateBytes

	if err := writeHooksFile(rawFile, hooksPath); err != nil {
		return 0, err
	}

	// 3 hooks: pre-tool-use, pre-invocation, stop
	return 3, nil
}

// UninstallHooks removes the Entire hook entry from .agents/hooks.json.
func (a *AntigravityAgent) UninstallHooks(ctx context.Context) error {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = "." // Fallback to CWD if not in a git repo
	}

	hooksPath := filepath.Join(repoRoot, ".agents", AgentsHooksFileName)
	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
	if err != nil {
		return nil //nolint:nilerr // No hooks file means nothing to uninstall
	}

	var rawFile map[string]json.RawMessage
	if err := json.Unmarshal(data, &rawFile); err != nil {
		return fmt.Errorf("failed to parse hooks.json: %w", err)
	}

	delete(rawFile, "entire")

	return writeHooksFile(rawFile, hooksPath)
}

// AreHooksInstalled checks if Entire hooks are installed.
func (a *AntigravityAgent) AreHooksInstalled(ctx context.Context) bool {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = "." // Fallback to CWD if not in a git repo
	}

	hooksPath := filepath.Join(repoRoot, ".agents", AgentsHooksFileName)
	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
	if err != nil {
		return false
	}

	var f HooksFile
	if err := json.Unmarshal(data, &f); err != nil {
		return false
	}

	cfg, ok := f["entire"]
	if !ok {
		return false
	}

	// Check at least one of our hook commands is present
	return hasEntireHookInToolHandlers(cfg.PreToolUse) ||
		hasEntireHookInToolHandlers(cfg.PostToolUse) ||
		hasEntireHookInSimpleHandlers(cfg.PreInvocation) ||
		hasEntireHookInSimpleHandlers(cfg.PostInvocation) ||
		hasEntireHookInSimpleHandlers(cfg.Stop)
}

// buildEntireHookConfig constructs the HookConfig for the "entire" entry.
func buildEntireHookConfig(cmdPrefix string, localDev bool) HookConfig {
	makeCmd := func(verb string) string {
		cmd := cmdPrefix + verb
		if !localDev {
			cmd = agent.WrapProductionSilentHookCommand(cmd)
		}
		return cmd
	}

	// PostToolUse and PostInvocation are deliberately NOT installed: neither
	// maps to a lifecycle event, and installing them spawns a no-op `entire`
	// subprocess on every completed tool call / model invocation. The struct
	// fields stay in HookConfig so the idempotency comparison detects (and
	// replaces) stale installs that still carry them.
	return HookConfig{
		PreToolUse: []ToolHandler{
			{
				Matcher: "*",
				Hooks:   []HookCommand{{Type: "command", Command: makeCmd("pre-tool-use")}},
			},
		},
		PreInvocation: []SimpleHandler{{Type: "command", Command: makeCmd("pre-invocation")}},
		Stop:          []SimpleHandler{{Type: "command", Command: makeCmd("stop")}},
	}
}

// writeHooksFile marshals rawFile and writes it to hooksPath, creating
// parent directories as needed.
func writeHooksFile(rawFile map[string]json.RawMessage, hooksPath string) error {
	return writeJSONMapFile(rawFile, hooksPath, "hooks.json")
}

// writeJSONMapFile marshals a raw JSON map with indentation and writes it to
// path, creating parent directories as needed. Shared by the repo-level
// hooks.json writer and the global agy settings.json writer.
func writeJSONMapFile(rawFile map[string]json.RawMessage, path, what string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return fmt.Errorf("failed to create directory for %s: %w", what, err)
	}

	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal %s: %w", what, err)
	}

	if err := os.WriteFile(path, output, 0o600); err != nil {
		return fmt.Errorf("failed to write %s: %w", what, err)
	}
	return nil
}

// hasEntireHookInToolHandlers checks if any ToolHandler entry is an Entire hook.
func hasEntireHookInToolHandlers(handlers []ToolHandler) bool {
	for _, th := range handlers {
		for _, hc := range th.Hooks {
			if agent.IsManagedHookCommand(hc.Command, entireHookPrefixes) {
				return true
			}
		}
	}
	return false
}

// hasEntireHookInSimpleHandlers checks if any SimpleHandler entry is an Entire hook.
func hasEntireHookInSimpleHandlers(handlers []SimpleHandler) bool {
	for _, sh := range handlers {
		if agent.IsManagedHookCommand(sh.Command, entireHookPrefixes) {
			return true
		}
	}
	return false
}

package antigravity

import "encoding/json"

// HooksFile maps hook names to their event configurations.
// The top-level key is the hook name (user-defined, e.g. "my-linter-hook").
type HooksFile = map[string]HookConfig

// HookConfig defines the event handlers for a named hook entry. It mirrors
// agy's hooks.json schema (https://antigravity.google/docs — Hooks), including
// event keys we don't install (PostToolUse/PostInvocation) so round-tripping a
// user's file never drops data and the install idempotency comparison detects
// stale Entire entries that still carry them.
type HookConfig struct {
	Enabled        *bool           `json:"enabled,omitempty"`
	PreToolUse     []ToolHandler   `json:"PreToolUse,omitempty"`
	PostToolUse    []ToolHandler   `json:"PostToolUse,omitempty"`
	PreInvocation  []SimpleHandler `json:"PreInvocation,omitempty"`
	PostInvocation []SimpleHandler `json:"PostInvocation,omitempty"`
	Stop           []SimpleHandler `json:"Stop,omitempty"`
}

// ToolHandler is a matcher + handlers entry used for PreToolUse / PostToolUse.
type ToolHandler struct {
	Matcher string        `json:"matcher,omitempty"`
	Hooks   []HookCommand `json:"hooks,omitempty"`
}

// SimpleHandler is a direct handler entry used for PreInvocation, PostInvocation, and Stop.
type SimpleHandler struct {
	Type    string `json:"type,omitempty"`
	Command string `json:"command"`
	Timeout int    `json:"timeout,omitempty"`
}

// HookCommand is a single executable hook command.
type HookCommand struct {
	Type    string `json:"type,omitempty"`
	Command string `json:"command"`
	Timeout int    `json:"timeout,omitempty"`
}

// Payload structs below decode only the fields the integration consumes.
// agy sends more (workspacePaths, artifactDirectoryPath, stepIdx,
// initialNumSteps, executionNum, terminationReason, error) — see the agy hooks
// docs for the full schema; add fields here only when something reads them.

// CommonPayload contains the system metadata fields the integration consumes
// from every hook payload.
type CommonPayload struct {
	ConversationID string `json:"conversationId"`
	TranscriptPath string `json:"transcriptPath"`
}

// ToolCall represents a proposed or completed tool invocation.
type ToolCall struct {
	Name string          `json:"name"`
	Args json.RawMessage `json:"args"`
}

// PreToolUsePayload is the stdin payload for the PreToolUse hook.
type PreToolUsePayload struct {
	CommonPayload

	ToolCall ToolCall `json:"toolCall"`
}

// InvocationPayload is the stdin payload for the PreInvocation hook.
//
// invocationNum is 0-indexed (the first model invocation of a conversation is
// 0). initialNumSteps is deliberately not decoded: agy inserts the user prompt
// as a step before the first model call, so it is already 1 on the first
// invocation and unusable as a "first?" signal.
type InvocationPayload struct {
	CommonPayload

	InvocationNum int `json:"invocationNum"`
}

// StopPayload is the stdin payload for the Stop hook.
type StopPayload struct {
	CommonPayload

	FullyIdle bool `json:"fullyIdle"` // Required
}
